#pragma unroll
          for (int e = 0; e < 8; e += 2) {
            float x0, x1;
            f2unpack(add2(f2pack(a[e], a[e + 1]), bk2), x0, x1);
            gelu2(x0, x1, dum);
            a[e] = x0; a[e + 1] = x1;
          }
#pragma unroll
          for (int e = 0; e < 8; e++) {
